update public.legal_organisations set
 overview='Old Square Chambers is a specialist civil set based in London, with a strong South West client base and nationwide work. Its practice includes employment and discrimination, professional discipline, personal injury, clinical negligence, travel, product liability, environmental law, health and safety, public inquiries and related public-law work.',
