update public.chambers set
 pupillage_overview='Old Square recruits a small number of 12-month pupils with the aim of selecting future tenants. Applications are made through the Pupillage Gateway. Shortlisting considers intellectual ability, written skills, advocacy potential, judgment, commitment to the set’s practice areas and interpersonal qualities; shortlisted candidates normally complete two interview rounds.',
 mini_pupillage_overview='Old Square offers three-day mini-pupillages in London during two weeks in June or July and again in September. Applicants should be sufficiently advanced in university or legal study, or be career changers with an informed interest in the set’s specialist work. Applications are anonymised and limited funding is available. The official page says information about the 2027 application window will be posted by early November 2026.',
 tenancy_overview='Old Square recruits pupils with a view to tenancy. Established-practitioner, probationary-tenancy and staff recruitment are excluded from Vacatory.',
 pupillage_gateway_member=true,
 pupillage_gateway_url='https://www.pupillagegateway.com/',
 research_status='verified',research_checked_on=date '2026-10-15',
 next_review_on=date '2026-11-03',updated_at=now()
where organisation_id='b1150875-7158-4906-8345-d030a98ccbda';

