update public.career_opportunities set slug='old-square-chambers-pupillage-2027-application-cycle',official_name='Old Square Chambers Pupillage — 2027 Application Cycle',public_name='Old Square Chambers Pupillage — 2027 Application Cycle',public_summary='Twelve-month pupillage at Old Square Chambers, recruited through the Pupillage Gateway with applications assessed against the chambers’ published selection criteria.',official_url='https://oldsquare.co.uk/join/pupillage/',application_url='https://www.pupillagegateway.com/',active=true,published=true,research_checked_on=date '2026-10-15',next_review_on=date '2026-11-23',updated_at=now() where id='c67fe388-4609-4751-bbe3-365913c858c9';

update public.career_opportunity_cycles set cycle_label='Old Square Chambers Pupillage — 2027 Application Cycle',application_year=2027,application_model='fixed_deadline',opens_on=date '2027-01-04',opens_at=time '11:00',opens_timezone='Europe/London',closes_on=date '2027-01-28',closes_at=time '23:59',closes_timezone='Europe/London',application_dates_text='Applications open at 11:00 on 4 January 2027 and close at 23:59 on 28 January 2027.',date_precision='exact',source_status='upcoming',audience_text='Aspiring barristers applying for pupillage through the Pupillage Gateway.',study_stage_text='Applicants who meet the Bar’s requirements for commencing pupillage; a minimum 2:1 degree is desirable.',academic_criteria='A minimum 2:1 degree is desirable. Intellectual ability is assessed from academic qualifications and other evidence.',eligibility_text='Applicants are assessed on intellectual ability, written skills, advocacy potential, sound judgment, commitment to Old Square’s practice areas and interpersonal qualities.',application_process_text='Apply through the Pupillage Gateway. Shortlisted applicants are normally invited to two interview rounds in March and April.',official_url='https://oldsquare.co.uk/join/pupillage/',application_url='https://www.pupillagegateway.com/',active=true,research_checked_on=date '2026-10-15',updated_at=now() where id='8f327acc-418e-4853-a335-b4efddb403fb';

update public.career_opportunities set official_name='Old Square Chambers School Work Experience — Summer 2027',public_name='Old Square Chambers School Work Experience — Summer 2027',public_summary='One-week London work-experience placement for students aged 16 to 18, including court observation and group activities about careers at the Bar.',official_url='https://oldsquare.co.uk/join/work-experience/',application_url='https://oldsquare.co.uk/join/work-experience/',active=true,published=true,research_checked_on=date '2026-10-15',next_review_on=date '2026-12-01',updated_at=now() where id='bd686c35-20d7-46e7-baec-1f1314976010';

update public.career_opportunity_cycles set cycle_label='Old Square Chambers School Work Experience — Summer 2027',application_year=2026,programme_year=2027,intake_year=2027,application_model='rolling',opens_on=date '2026-11-30',closes_on=null,application_dates_text='Applications open on 30 November 2026 and close when 80 fully completed applications have been received.',programme_starts_on=date '2027-06-28',programme_ends_on=date '2027-07-09',programme_dates_text='Placements run from 28 June to 2 July 2027 and from 5 to 9 July 2027.',date_precision='exact',duration_text='One week',places_text='12 places; applications capped at 80 completed forms',source_status='upcoming',audience_text='Students aged 16 to 18 who can attend one of the two full placement weeks.',study_stage_text='School students aged 16 to 18.',academic_criteria=null,eligibility_text='Applicants must be aged 16 to 18 and available for either 28 June to 2 July 2027 or 5 to 9 July 2027.',application_process_text='Apply using the form published on the official page. Applications are anonymised and assessed against a scoring matrix.',assessments_text='Anonymised application review against a scoring matrix.',progression_route_text=null,programme_structure_text='Court observation and group activities introducing careers at the Bar and the pupillage application process.',funding_text=null,expenses_text=null,travel_support_text='Funding is available to help successful applicants with travel expenses.',accommodation_support_text=null,right_to_work_text=null,disability_support_text='Reasonable adjustments are available for the application process and placement.',source_status_note=null,additional_details_text=null,may_close_early=true,official_url='https://oldsquare.co.uk/join/work-experience/',application_url='https://oldsquare.co.uk/join/work-experience/',active=true,research_checked_on=date '2026-10-15',updated_at=now() where id='bbeda196-1a19-43c8-adab-a079d968c541';

insert into public.career_opportunities(organisation_id,opportunity_type_id,slug,official_name,public_name,public_summary,delivery_mode,official_url,application_url,active,published,research_checked_on,next_review_on)
select 'b1150875-7158-4906-8345-d030a98ccbda','06f22221-7e57-4379-b2a1-fcbec5d4f4bb','old-square-chambers-10000-black-interns-bar-2027','10,000 Black Interns — The Bar 2027 — Old Square Participating Chambers','10,000 Black Interns — The Bar 2027 — Old Square Participating Chambers','Paid Bar workstream for eligible Black students and recent graduates. Interns rotate across participating chambers and organisations; Old Square confirms that it participates in the Bar Council scheme, but allocation to a particular host is not guaranteed.','in_person','https://oldsquare.co.uk/about/equality-diversity-and-inclusion/','https://10000internsfoundation.com/students-graduates/10000-black-interns/',true,true,date '2026-10-15',date '2026-11-02'
where not exists(select 1 from public.career_opportunities where slug='old-square-chambers-10000-black-interns-bar-2027');

insert into public.career_opportunity_cycles(opportunity_id,cycle_key,cycle_label,application_year,programme_year,intake_year,application_model,opens_on,closes_on,application_dates_text,programme_dates_text,date_precision,duration_text,source_status,audience_text,study_stage_text,eligibility_text,application_process_text,programme_structure_text,funding_text,right_to_work_text,official_url,application_url,active,research_checked_on)
select o.id,'old-square-10000-black-interns-bar-2027',o.official_name,2026,2027,2027,'fixed_deadline',date '2026-10-05',date '2026-11-01','Applications for the Summer 2027 programme close on 1 November 2026.','Paid internships take place between May and September 2027; dates vary by host.','exact','At least six weeks','open','Eligible Black students and recent graduates interested in the Bar.','Applicants must be aged 18 or over and meet the Foundation’s UK study or recent-graduate criteria.','Applicants must be Black African, Black Caribbean, Black British or of mixed Black heritage; must not previously have secured an internship through the programme; and must hold the required unrestricted right to work in the United Kingdom.','Apply to the 10,000 Interns Foundation and select The Bar workstream. Host allocation is managed by the programme.','The Bar workstream rotates interns across participating chambers and organisations within one region.','Internships are paid.','Applicants must already have an unrestricted right to work full-time in the United Kingdom.','https://oldsquare.co.uk/about/equality-diversity-and-inclusion/','https://10000internsfoundation.com/students-graduates/10000-black-interns/',true,date '2026-10-15'
from public.career_opportunities o where o.slug='old-square-chambers-10000-black-interns-bar-2027' and not exists(select 1 from public.career_opportunity_cycles c where c.opportunity_id=o.id);

delete from public.career_opportunity_routes where route_kind='unresolved' and opportunity_id in (select id from public.career_opportunities where slug='old-square-chambers-10000-black-interns-bar-2027');
insert into public.career_opportunity_routes(opportunity_id,route_kind,country_id,city_id,route_note,route_status,display_order,active)
select o.id,'physical_city',47,139,'London / programme-managed Bar rotation','confirmed',10,true from public.career_opportunities o where o.slug='old-square-chambers-10000-black-interns-bar-2027' and not exists(select 1 from public.career_opportunity_routes r where r.opportunity_id=o.id and r.city_id=139);

